# AUTOGENERATED FILE
from pymol import cmd
import pymol


def show_ligand_environment(ligand_selection="hetatm", distance=5.0, style="sticks"):
    """
    DESCRIPTION
    Display ligand and its surrounding residues with well-defined colors and presentations.

    PARAMETERS
    ligand_selection: str - Selection string for ligand (default: "hetatm")
    distance: float - Distance cutoff in Angstroms (default: 5.0)
    style: str - Representation style: "sticks", "spheres", "cartoon" (default: "sticks")
    """

    # Clear previous selections
    cmd.delete("ligand_env_*")

    # Create selections
    ligand_sel = f"({ligand_selection})"
    surrounding_sel = (
        f"(byres ({ligand_sel} around {distance})) and (sidechain or name CA)"
    )

    # Create named selections
    cmd.select("ligand_env_ligand", ligand_sel)
    cmd.select("ligand_env_surrounding", surrounding_sel)
    cmd.select("ligand_env_backbone", f"({surrounding_sel}) and name CA")
    cmd.select("ligand_env_sidechains", f"({surrounding_sel}) and sidechain")

    # Hide everything first
    cmd.hide("everything")

    # Show ligand
    if style == "sticks":
        cmd.show("sticks", "ligand_env_ligand")
    elif style == "spheres":
        cmd.show("spheres", "ligand_env_ligand")
    else:
        cmd.show("sticks", "ligand_env_ligand")

    # Show surrounding residues
    cmd.show("sticks", "ligand_env_sidechains")
    cmd.show("spheres", "ligand_env_backbone")

    # Set colors
    cmd.color("orange", "ligand_env_ligand")  # Ligand in orange
    cmd.color("cyan", "ligand_env_sidechains")  # Sidechains in cyan
    cmd.color("red", "ligand_env_backbone")  # CA atoms in red

    # Color by element for ligand
    cmd.util.cnc("ligand_env_ligand")  # Carbon=cyan, Nitrogen=blue, Oxygen=red

    # Set sphere scale for CA atoms
    cmd.set("sphere_scale", 0.3, "ligand_env_backbone")

    # Show hydrogen bonds - 为每个配体对象创建单独的氢键对象
    ligand_objects = cmd.get_names("objects", selection="ligand_env_ligand")
    for ligand_obj in ligand_objects:
        hbond_name = f"hbonds_{ligand_obj}"
        cmd.distance(hbond_name, ligand_obj, "ligand_env_surrounding", 3.5, mode=2)
        cmd.color("yellow", hbond_name)
        cmd.set("dash_gap", 0.2, hbond_name)
        # 将氢键对象组织到对应的配体对象组中
        cmd.group(f"ligand_env_{ligand_obj}", f"{ligand_obj} {hbond_name}")

    # Center view on ligand
    cmd.center("ligand_env_ligand")
    cmd.zoom("ligand_env_ligand or ligand_env_surrounding", buffer=2)

    print(f"Ligand environment displayed:")
    print(f"  - Ligand: {cmd.count_atoms('ligand_env_ligand')} atoms")
    print(
        f"  - Surrounding residues: {cmd.count_atoms('ligand_env_surrounding')} atoms"
    )
    print(f"  - Distance cutoff: {distance} Å")


def show_ligand_surface(ligand_selection="hetatm", distance=5.0, transparency=0.3):
    """
    DESCRIPTION
    Show molecular surface around ligand binding site.

    PARAMETERS
    ligand_selection: str - Selection string for ligand (default: "hetatm")
    distance: float - Distance cutoff in Angstroms (default: 5.0)
    transparency: float - Surface transparency (0.0-1.0, default: 0.3)
    """

    # 为每个配体对象创建单独的表面
    ligand_objects = cmd.get_names("objects", selection=f"({ligand_selection})")

    for ligand_obj in ligand_objects:
        # Create surface selection for this specific ligand
        surface_sel = f"(byres ({ligand_obj} around {distance}))"
        surface_name = f"surface_{ligand_obj}"
        cmd.select(surface_name, surface_sel)

        # Show surface
        cmd.show("surface", surface_name)
        cmd.color("palegreen", surface_name)
        cmd.set("transparency", transparency, surface_name)

        # 将表面对象组织到对应的配体对象组中
        if cmd.count_atoms(f"ligand_env_{ligand_obj}") > 0:
            cmd.group(f"ligand_env_{ligand_obj}", surface_name)
        else:
            cmd.group(f"ligand_env_{ligand_obj}", f"{ligand_obj} {surface_name}")

    print(f"Surface displayed with {transparency} transparency")


def color_by_properties(selection="ligand_env_surrounding"):
    """
    DESCRIPTION
    Color surrounding residues by their properties.

    PARAMETERS
    selection: str - Selection to color (default: "ligand_env_surrounding")
    """

    # Color by residue type
    cmd.color("red", f"({selection}) and (resn ASP+GLU)")  # Acidic - red
    cmd.color("blue", f"({selection}) and (resn LYS+ARG+HIS)")  # Basic - blue
    cmd.color("green", f"({selection}) and (resn SER+THR+ASN+GLN)")  # Polar - green
    cmd.color(
        "yellow", f"({selection}) and (resn ALA+VAL+LEU+ILE+MET+PHE+TRP+TYR)"
    )  # Hydrophobic - yellow
    cmd.color("orange", f"({selection}) and (resn GLY+PRO+CYS)")  # Special - orange

    print("Residues colored by properties:")
    print("  Red: Acidic (ASP, GLU)")
    print("  Blue: Basic (LYS, ARG, HIS)")
    print("  Green: Polar (SER, THR, ASN, GLN)")
    print("  Yellow: Hydrophobic (ALA, VAL, LEU, ILE, MET, PHE, TRP, TYR)")
    print("  Orange: Special (GLY, PRO, CYS)")


def label_residues(selection="ligand_env_surrounding"):
    """
    DESCRIPTION
    Label surrounding residues with their names and numbers.

    PARAMETERS
    selection: str - Selection to label (default: "ligand_env_surrounding")
    """

    cmd.label(f"({selection}) and name CA", "resn+resi")
    cmd.set("label_color", "black")
    cmd.set("label_size", 10)

    print("Residues labeled with name and number")


def clean_ligand_display():
    """
    DESCRIPTION
    Clean up all ligand environment display objects.
    """

    cmd.delete("ligand_env_*")
    cmd.hide("labels")
    cmd.show("cartoon")
    cmd.color("gray", "all")

    print("Ligand environment display cleaned")


def show_distances(
    ligand_selection="hetatm", target_selection="ligand_env_surrounding", cutoff=4.0
):
    """
    DESCRIPTION
    Show distances between ligand and surrounding residues, organized by ligand object.

    PARAMETERS
    ligand_selection: str - Selection string for ligand (default: "hetatm")
    target_selection: str - Selection for target atoms (default: "ligand_env_surrounding")
    cutoff: float - Distance cutoff in Angstroms (default: 4.0)
    """

    ligand_objects = cmd.get_names("objects", selection=f"({ligand_selection})")

    for ligand_obj in ligand_objects:
        distance_name = f"distances_{ligand_obj}"
        cmd.distance(distance_name, ligand_obj, target_selection, cutoff, mode=0)
        cmd.color("magenta", distance_name)
        cmd.set("dash_width", 2, distance_name)

        # 将距离对象组织到对应的配体对象组中
        if cmd.count_atoms(f"ligand_env_{ligand_obj}") > 0:
            cmd.group(f"ligand_env_{ligand_obj}", distance_name)
        else:
            cmd.group(f"ligand_env_{ligand_obj}", f"{ligand_obj} {distance_name}")

    print(f"Distances shown with {cutoff} Å cutoff")


def organize_objects():
    """
    DESCRIPTION
    Organize all ligand environment objects into proper groups.
    """

    # Get all ligand objects
    ligand_objects = cmd.get_names("objects", selection="ligand_env_ligand")

    for ligand_obj in ligand_objects:
        group_name = f"ligand_env_{ligand_obj}"

        # Find related objects
        related_objects = []
        all_objects = cmd.get_object_list()

        for obj in all_objects:
            if (
                obj.startswith(f"hbonds_{ligand_obj}")
                or obj.startswith(f"surface_{ligand_obj}")
                or obj.startswith(f"distances_{ligand_obj}")
                or obj == ligand_obj
            ):
                related_objects.append(obj)

        # Create group
        if related_objects:
            cmd.group(group_name, " ".join(related_objects))

    print("Objects organized into ligand-specific groups")


def preset_binding_site(ligand_selection="hetatm", distance=5.0):
    """
    DESCRIPTION
    Apply a comprehensive binding site visualization preset.

    PARAMETERS
    ligand_selection: str - Selection string for ligand (default: "hetatm")
    distance: float - Distance cutoff in Angstroms (default: 5.0)
    """

    # Main environment display
    show_ligand_environment(ligand_selection, distance, "sticks")

    # Add surface
    show_ligand_surface(ligand_selection, distance, 0.2)

    # Color by properties
    color_by_properties()

    # Label residues
    label_residues()

    # Show distances
    show_distances(ligand_selection, "ligand_env_surrounding", 4.0)

    # Organize objects into groups
    organize_objects()

    # Set nice viewing parameters
    cmd.set("stick_radius", 0.15)
    cmd.set("sphere_scale", 0.25)
    cmd.set("mesh_width", 2)
    cmd.set("dash_width", 3)

    # Set background
    cmd.bg_color("white")

    print("Binding site preset applied successfully!")


def quick_ligand_view(distance=4.0):
    """
    DESCRIPTION
    Quick view of ligand environment with default settings.

    PARAMETERS
    distance: float - Distance cutoff in Angstroms (default: 4.0)
    """

    preset_binding_site("hetatm", distance)


# Register commands in PyMOL
cmd.extend("show_ligand_env", show_ligand_environment)
cmd.extend("show_ligand_surface", show_ligand_surface)
cmd.extend("show_distances", show_distances)
cmd.extend("organize_objects", organize_objects)
cmd.extend("color_by_props", color_by_properties)
cmd.extend("label_residues", label_residues)
cmd.extend("clean_ligand", clean_ligand_display)
cmd.extend("preset_binding", preset_binding_site)
cmd.extend("quick_ligand", quick_ligand_view)

print("Ligand environment plugin loaded successfully!")
print("Available commands:")
print("  show_ligand_env [selection] [distance] [style]")
print("  show_ligand_surface [selection] [distance] [transparency]")
print("  show_distances [ligand_selection] [target_selection] [cutoff]")
print("  organize_objects")
print("  color_by_props [selection]")
print("  label_residues [selection]")
print("  clean_ligand")
print("  preset_binding [selection] [distance]")
print("  quick_ligand [distance]")
